function remove(Tree storage _tree,uint _value) internal {
 Node storage n = _tree.nodes[_value];
 if (_value==0) {
 if (n.dupes==0) {
 return;
 }
 } else {
 if (n.count==0) {
 return;
 }
 }
 if (n.dupes>0) {
 n.dupes--;
 if (_value!=0) {
 n.count--;
 }
 fixParents(_tree,n.parent,n.side);
 } else {
 removeHelper(_tree,_value);
 }
 },0

