function nextRune(slice self, slice rune) internal returns (slice) {
 rune._ptr = self._ptr;
 if (self._len == 0) {
 rune._len = 0;
 return rune;
 }
 uint len;
 uint b;
 assembly { b := and(mload(sub(mload(add(self, 32)), 31)), 0xFF) }
 if (b < 0x80) {
 len = 1;
 } else if(b < 0xE0) {
 len = 2;
 } else if(b < 0xF0) {
 len = 3;
 } else {
 len = 4;
 }
 if (len > self._len) {
 rune._len = self._len;
 self._ptr += self._len;
 self._len = 0;
 return rune;
 }
 self._ptr += len;
 self._len -= len;
 rune._len = len;
 return rune;
 },0

