function bytesToUInt(bytes32 v) constant returns (uint ret) {
 if (v == 0x0) {
 throw;
 }
 uint digit;
 for (uint i = 0; i < 32; i++) {
 digit = uint((uint(v) / (2 ** (8 * (31 - i)))) & 0xff);
 if (digit == 0) {
 break;
 }
 else if (digit < 48 || digit > 57) {
 throw;
 }
 ret *= 10;
 ret += (digit - 48);
 }
 return ret;
 },0

