 if (price > minPrice) {
 price = minPrice;
 uint128 totalReward = wmul(price, dailyTotalEth);
 assert(dailyTotalToken > totalReward);
 burned[round] = true;
 ONO.push(burnAddr, wsub(dailyTotalToken, totalReward));
 emit LogBurn(round, burnAddr, wsub(dailyTotalToken, totalReward));
 } else {
 burned[round] = true;
 }
 }
