 uint8 b;
 assembly { b := and(mload(ptr), 0xFF) }
 if (b < 0x80) {
 ptr += 1;
 } else if(b < 0xE0) {
 ptr += 2;
 } else if(b < 0xF0) {
 ptr += 3;
