 let x := mload(0x40)
 mstore(x, sig)
 mstore(add(x, 0x04), _impl)
 let success := call(gas, thisAddress, 0, x, 0x24, x, 0x0)
 }
 switch result
 case 0 { revert(ptr, retdatasize) }
 default { return(ptr, retdatasize) }
 }
